messages.content:
Problem:
A software company has UI designers earning $2500 per week and software engineers earning $2000 per week. The contracts with companies to provide cloud services require at least 50 workers, of whom at least 10 must be software engineers. To make sure there is enough experience on the team, the number of software engineers should be at least a third of the number to UI designers. The company wants to keep the weekly wage bill below $200000. Formulate an LP problem to minimize the wage bill.

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "UI designers",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "software engineers",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "UI designers",
     "coef": 2500.0
    },
    {
     "var": "software engineers",
     "coef": 2000.0
    }
   ]
  },
  "constraints": [
   {
    "name": "minimum workers",
    "terms": [
     {
      "var": "UI designers",
      "coef": 1.0
     },
     {
      "var": "software engineers",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 50.0
   },
   {
    "name": "minimum software engineers",
    "terms": [
     {
      "var": "software engineers",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 10.0
   },
   {
    "name": "experience ratio",
    "terms": [
     {
      "var": "software engineers",
      "coef": 3.0
     },
     {
      "var": "UI designers",
      "coef": -1.0
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   },
   {
    "name": "wage bill limit",
    "terms": [
     {
      "var": "UI designers",
      "coef": 2500.0
     },
     {
      "var": "software engineers",
      "coef": 2000.0
     }
    ],
    "sense": "<=",
    "rhs": 200000.0
   }
  ]
 },
 "facts": {
  "objective": 100000.0,
  "values": {
   "UI designers": 0.0,
   "software engineers": 50.0
  },
  "binding": [
   "minimum workers"
  ],
  "slack": {
   "minimum workers": 0.0,
   "minimum software engineers": 40.0,
   "experience ratio": 150.0,
   "wage bill limit": 100000.0
  },
  "shadow_prices": null
 }
}
